namespace sv_c38aa605ce234d179454e9d2d60d14a4.Services;

public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";
    private string _currentWarehouseName = "Warehouse A";

    public string CurrentWarehouseId => _currentWarehouseId;
    public string CurrentWarehouseName => _currentWarehouseName;

    public event Func<Task>? OnWarehouseChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
        ("WH-004", "Warehouse D")
    };

    public async Task SetWarehouseAsync(string warehouseId)
    {
        var warehouse = AvailableWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse == default) return;

        _currentWarehouseId = warehouse.Id;
        _currentWarehouseName = warehouse.Name;

        if (OnWarehouseChanged is not null)
        {
            await OnWarehouseChanged.Invoke();
        }
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

namespace sv_c38aa605ce234d179454e9d2d60d14a4.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentLowStockCount { get; private set; }

    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChangedAsync;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query — returns a random number between 0 and 15
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _cts = new CancellationTokenSource();
                _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
                _ = PollLoopAsync(_cts.Token);
            }
        }
    }

    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _cts?.Cancel();
                _timer?.Dispose();
                _timer = null;
                _cts = null;
            }
        }
    }

    public async Task RefreshAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        CurrentLowStockCount = count;

        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        // Immediately fetch on start
        await RefreshAsync();

        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(cancellationToken))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task HandleWarehouseChangedAsync()
    {
        // When warehouse changes, immediately refresh if polling is active
        lock (_lock)
        {
            if (_subscriberCount == 0) return;
        }

        await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChangedAsync;
        _cts?.Cancel();
        _timer?.Dispose();
        OnAlertCountChanged = null;
    }
}

