@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId" @onchange="OnWarehouseSelectedAsync">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private async Task OnWarehouseSelectedAsync(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            await WarehouseState.SetWarehouseAsync(warehouseId);
        }
    }

    private Task HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span> Alerts
    @if (_lowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill ms-1">@_lowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill ms-1">0</span>
    }
</span>

@code {
    private int _lowStockCount;

    protected override void OnInitialized()
    {
        _lowStockCount = AlertService.CurrentLowStockCount;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private Task HandleAlertCountChanged()
    {
        _lowStockCount = AlertService.CurrentLowStockCount;
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    private Task HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

