@code {
    private int _lowStockCount;
    private DateTime _lastUpdated = DateTime.Now;
    private bool _isPolling;

    protected override void OnInitialized()
    {
        _lowStockCount = AlertService.CurrentLowStockCount;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;

        AlertService.StartPolling();
        _isPolling = true;
    }

    private Task HandleAlertCountChanged()
    {
        _lowStockCount = AlertService.CurrentLowStockCount;
        _lastUpdated = DateTime.Now;
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    private Task HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

